This is my callback function:

```

/* --- Timer Input Capture Callback Function --- */

void HAL_TIM_UpdateCallback(hal_tim_handle_t *htim)

{

if (htim == mx_tim2_gethandle())

{

HAL_GPIO_TogglePin(HAL_GPIOA, HAL_GPIO_PIN_5); // built in LED

}

